import{z as E,x as A,o as t,c as p,q as n,j as l,D as e,d as o,s,S as d,b as r}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"自动微分的正向与反向模式","description":"","frontmatter":{"title":"自动微分的正向与反向模式","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/autograd-two-modes.md","filePath":"llm/autograd-two-modes.md","lastUpdated":1791413859000}'),D={name:"llm/autograd-two-modes.md"};function B(m,a,c,u,h,_){const i=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=n('<h1 id="自动微分的正向与反向模式" tabindex="-1">自动微分的正向与反向模式 <a class="header-anchor" href="#自动微分的正向与反向模式" aria-label="Permalink to &quot;自动微分的正向与反向模式&quot;">​</a></h1><div class="epigraph"><p>同一条链式法则，从输入往输出推是正向模式，从输出往输入推是反向模式；谁便宜，取决于自变量多还是因变量多。</p><footer>—— 据 Griewank &amp; Walther, Evaluating Derivatives；Baydin et al., Automatic Differentiation in Machine Learning, JMLR 2018 整理</footer></div><p><a href="/llm/backprop-layerwise">反向传播一行一层</a>默认从损失往参数走。本课不重写线性层的两次 GEMM。缺口是：自动微分还有另一种扫法——正向模式：每个中间量携带对某个输入的导数，随前向一起走。训练几乎总用反向，因为 \\(L\\) 是标量、\\(\\theta\\) 是百万到千亿维。正向模式在「少数输入、许多输出」时才更便宜。本课把两种复杂度钉住，避免把 backprop 当成 AD 的唯一定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>计算图有 \\(n\\) 个独立输入、\\(m\\) 个输出。要全部一阶导数，即 \\(m\\times n\\) 的 Jacobian。正向模式选一个输入方向 \\(v\\)，一次扫图得到 \\(Jv\\)（Jacobian-vector）；要满 Jacobian，约需 \\(n\\) 次。反向模式选一个输出余向量 \\(u\\)，一次扫图得到 \\(u^\\top J\\)（vector-Jacobian）；要满 Jacobian，约需 \\(m\\) 次。缺口不是新的局部导数，而是这次计数：深度学习训练 \\(m=1\\)、\\(n\\) 极大，故反向一次就够；若问「每个输出对某一个输入」的敏感度，\\(n=1\\) 则正向一次就够。</p><p>框架里的 autograd 默认反向。Jacobian-vector 接口（有的叫 forward-over-reverse）用于二阶、用于梯度惩罚，那是后话。本课只要求能回答：为什么训练不跑正向 AD。</p><h3 id="正向模式不是「再做一次前向传播」" tabindex="-1">正向模式不是「再做一次前向传播」 <a class="header-anchor" href="#正向模式不是「再做一次前向传播」" aria-label="Permalink to &quot;正向模式不是「再做一次前向传播」&quot;">​</a></h3><p>前向传播算的是值。正向 AD 算的是值与切空间里的种子一起走：每个张量多带一个与自身同形的切向量。开销大约是常数倍的前向，不是「免费」。反向 AD 则要保存中间值，内存与图深度（或与检查点策略）相关。把正向 AD 理解成「不占内存的反向」，形状和次数都错：它省的是反向那次扫，不省对每个输入各扫一次的次数。</p><p><span class="marginnote">标量损失对参数的梯度是 \\(1\\times n\\) 的行。反向一次得到整行。正向要对每个参数种子跑一次，才能填满这一行。这就是训练不用正向模式的全部理由。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记图为复合 \\(f=f_k\\circ\\cdots\\circ f_1\\)。正向 AD：选 \\(v\\)，令 \\(\\dot x_0=v\\)，递推 \\(\\dot x_{i}=J_{f_i}\\dot x_{i-1}\\)，最后得到 \\(J_f v\\)。反向 AD：选 \\(u\\)，令 \\(\\bar x_k=u\\)，递推 \\(\\bar x_{i-1}=J_{f_i}^\\top\\bar x_i\\)，最后得到 \\(J_f^\\top u\\)。实现上，正向 AD 可与数值前向融合；反向 AD 要先完整前向再逆序。混合模式对中间层切分，用于极深图的检查点，本课只点名，不展开。</p><p><span class="marginnote">把记号翻译成话：\\(Jv\\) 读作「Jacobian 乘向量」——\\(J\\) 是所有偏导排成的大表，\\(v\\) 是你挑的输入方向，\\(Jv\\) 回答「输出沿这个方向变化多快」。反向的 \\(u^\\top J\\) 则反过来问「这个输出扰动该由哪些输入负责」。两个式子都是矩阵乘向量，谁便宜取决于表的两边哪边大。</span></p>',12)),(t(),l(d,null,{default:e(()=>[s(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20IN%5B%22%E8%AE%B8%E5%A4%9A%E5%8F%82%E6%95%B0%22%5D%20--%3E%20FWD%5B%22%E6%AD%A3%E5%90%91%E6%A8%A1%E5%BC%8F%20J%20%E4%B9%98%20v%22%5D%0A%20%20FWD%20--%3E%20OUTS%5B%22%E8%AE%B8%E5%A4%9A%E8%BE%93%E5%87%BA%E6%96%B9%E5%90%91%22%5D%0A%20%20LOSS%5B%22%E4%B8%80%E4%B8%AA%E6%8D%9F%E5%A4%B1%22%5D%20--%3E%20REV%5B%22%E5%8F%8D%E5%90%91%E6%A8%A1%E5%BC%8F%20u%20%E8%BD%AC%E7%BD%AE%E4%B9%98%20J%22%5D%0A%20%20REV%20--%3E%20GRADS%5B%22%E5%AF%B9%E6%89%80%E6%9C%89%E5%8F%82%E6%95%B0%E7%9A%84%E6%A2%AF%E5%BA%A6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[o("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"复杂度差来自矩阵乘法结合律：\\((AB)v\\) 与 \\(u^\\top(AB)\\) 的结合顺序不同，中间维被收缩的次数就不同。层很宽时，物化完整 Jacobian 不可能；两种模式都只传播向量。反向模式还要面对内存：残差块可以把反向路径变短，检查点则用重计算换存储。这些是系统课的主题；机制上只需记住，反向不是计算上无条件更优，只是对「标量损失 + 大量参数」更优。",-1)),(t(),l(d,null,{default:e(()=>[s(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20FWD%5B%22%E6%AD%A3%E5%90%91%E6%A8%A1%E5%BC%8F%EF%BC%9A%E5%AF%BC%E6%95%B0%E4%BE%BF%E7%AD%BE%E9%9A%8F%E5%80%BC%E5%89%8D%E8%BF%9B%22%5D%0A%20%20%20%20X1%5B%22x%3D3%2C%20dx%3D1%22%5D%20--%3E%20Y1%5B%22y%3D6%2C%20dy%3Dw%C2%B7dx%3D2%22%5D%0A%20%20%20%20Y1%20--%3E%20L1%5B%22L%3D36%2C%20dL%3D2y%C2%B7dy%3D24%22%5D%0A%20%20end%0A%20%20subgraph%20REV%5B%22%E5%8F%8D%E5%90%91%E6%A8%A1%E5%BC%8F%EF%BC%9A%E4%BC%B4%E9%9A%8F%E9%87%8F%E4%BB%8E%E6%8D%9F%E5%A4%B1%E5%80%92%E6%8E%A8%22%5D%0A%20%20%20%20L2%5B%22dL%3D1%22%5D%20--%3E%20Y2%5B%22dy%3D2y%C2%B7dL%3D12%22%5D%0A%20%20%20%20Y2%20--%3E%20X2%5B%22dx%3Dw%C2%B7dy%3D24%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">上图是同一个玩具函数 \\(y=wx,\\ L=y^2\\)（取 \\(w=2,x=3\\)）的两种扫法：正向带着种子 \\(\\dot x=1\\) 一路前进，一步就拿到 \\(dL/dx=24\\)；反向从 \\(dL=1\\) 倒推。只要 1 个输入，两种模式都只扫一遍——差别要等输入维或输出维变大才显现。</span></p><p>数值梯度检验常用正向有限差分对单个参数，那是 \\(O(n)\\) 次前向，只能抽样若干坐标。它检验的是局部规则写得对不对，不能替代 AD。</p><p><span class="marginnote">有限差分不是第三种自动微分：它用 \\((L(x+\\varepsilon)-L(x-\\varepsilon))/2\\varepsilon\\) 估一个坐标的导数。\\(\\varepsilon\\) 取大了截断误差大，取小了两个相近数相消、浮点噪声吞掉信号，两头都不准——所以只当抽查手段，不当生产工具。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不推导 Hessian-vector 的两次反向。下一课<a href="/llm/vanish-explode-grad">梯度消失与爆炸</a>问的是反向路径上局部增益的连乘，不是 AD 模式选错。后课默认：训练用反向 AD；说到 Jacobian-vector，才考虑正向或正向嵌反向。</p><p><span class="marginnote">什么时候正向模式反而划算？只要「少量输出对某个输入」的敏感度时：比如研究单个传感器输入如何影响几千个输出，正向扫一遍就得 \\(Jv\\)，反向却要对每个输出各扫一遍。深度学习正好倒过来（参数百万、损失只有 1 个），所以训练永远选反向。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正向 AD 一次得 \\(Jv\\)，次数随输入维；反向 AD 一次得 \\(u^\\top J\\)，次数随输出维。</li><li>训练 \\(m=1\\)，故反向一次给出全部参数梯度。</li><li>正向 AD 不是免费前向，每个张量携带切向量。</li><li>反向 AD 的代价在内存与检查点，不在「算不出梯度」。</li><li>出处：Griewank &amp; Walther；Baydin et al., JMLR 2018。</li></ul>',8))])}const v=E(D,[["render",B]]);export{b as __pageData,v as default};
